/* @component: .bunner-swiper */
function initSwiper() {
  if (typeof Swiper !== 'undefined') {
    const swiper = new Swiper('.bunner-swiper', {

      slidesPerView: 1,

      loop: true,
      speed: 800,

      pagination: {
        el: '.bunner-swiper .swiper-pagination',
        clickable: true,

        renderBullet: function (index, className) {
          // 1. Получаем все слайды в верстке
          const slides = document.querySelectorAll('.bunner-swiper .swiper-slide:not(.swiper-slide-duplicate)');

          // 2. Достаем текст из data-title конкретного слайда
          let slideTitle = '';
          if (slides[index]) {
            slideTitle = slides[index].getAttribute('data-title') || 'Слайд';
          }

          // 3. Возвращаем кастомную разметку буллита. 
          // index + 1 — это номер слайда (начиная с 1).
          return `<span class="${className}">
                    <span class="bullet-number">${index + 1}</span>
                    <span class="bullet-text">${slideTitle}</span>
                  </span>`;
        }
      },
      navigation: {
        nextEl: '.bunner-swiper .swiper-button-next',
        prevEl: '.bunner-swiper .swiper-button-prev'
      },

      observer: true,
      observeParents: true
    });

    setTimeout(() => swiper.update(), 200);
  } else {
    setTimeout(initSwiper, 150);
  }
}

if (!document.getElementById('swiper-js')) {
  const script = document.createElement('script');
  script.id = 'swiper-js';
  script.src = 'https://cdn.jsdelivr.net/npm/swiper@11/swiper-bundle.min.js';
  script.onload = initSwiper;
  document.head.appendChild(script);
} else {
  initSwiper();
}
